/// The gallery's example of `ExpressionEditor`, with its settings taken from the story.
#[allow(unused_variables, unused_mut, clippy::redundant_clone, clippy::let_and_return, clippy::clone_on_copy)]
fn render(args: &Args) -> AnyView {
    Box::new({
        let arg_preview = args.text("preview");
        let arg_preview_error = args.text("preview_error");
        let arg_rows = args.number("rows") as usize;

        let expression = State::new(args.text("expression"));
        {
            let mut it = ExpressionEditor::new(expression.binding())
                .field(FilterField::new("Quantity", "Quantity", FilterFieldKind::Number))
                .field(FilterField::new("UnitPrice", "Unit price", FilterFieldKind::Number))
                .parameter(FilterField::new("MinTotal", "Least total", FilterFieldKind::Number));
            if !arg_preview.is_empty() {
                it = it.preview(arg_preview.clone());
            }
            if !arg_preview_error.is_empty() {
                it = it.preview_error(arg_preview_error.clone());
            }
            it = it.rows(arg_rows);
            it
        }
    })
}

impl ComponentBook for ExpressionEditor {
    fn book() -> Meta {
        Meta::new("Actions and inputs/ExpressionEditor", render)
            .summary("Writes an expression with fields, functions and operators at hand.")
            .arg(ArgType::text("preview", "").description("Empty leaves it as the component has it."))
            .arg(ArgType::text("preview_error", "").description("Empty leaves it as the component has it."))
            .arg(ArgType::number("rows", 5.0, 0.0, 20.0, 1.0))
            .arg(
                ArgType::text("expression", "[Quantity] * [UnitPrice]")
                    .description("How the example starts."),
            )
            .story("Example", Args::new())
    }
}
